// Split the KB on '## ' headings rather than a fixed character window. A resume section
// is already a coherent unit of meaning, and a blind window would cut a role away from
// its own bullets — exactly the retrieval failure that makes RAG look bad on short docs.
const markdown = $json.body?.markdown ?? '';
if (!markdown.trim()) {
  throw new Error('No markdown in request body');
}

const MAX_CHARS = 1500;
const MIN_SUBSTANCE = 60;

// A TODO line is a question for Carlo, not a fact about him. Embedding one would let the
// bot retrieve a question as though it were an answer. The answer, when it exists, lives
// in the '>' quote under it — so drop the prompt and its wrapped continuation lines, and
// keep whatever the quote holds.
function stripScaffolding(body) {
  const lines = body.split('\n');
  const kept = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (/^\s*[-*]?\s*\*{0,2}TODO/.test(line)) {
      // Swallow the prompt's wrapped continuation lines: indented, not a quote, not a
      // new bullet or heading.
      while (
        i + 1 < lines.length &&
        /^\s{2,}\S/.test(lines[i + 1]) &&
        !/^\s*>/.test(lines[i + 1]) &&
        !/^\s*[-*]\s/.test(lines[i + 1]) &&
        !/^#{1,6}\s/.test(lines[i + 1])
      ) {
        i++;
      }
      continue;
    }

    // '>' marks an answer slot. Empty means unanswered; text means Carlo filled it in.
    if (/^\s*>/.test(line)) {
      const answer = line.replace(/^\s*>\s?/, '').trim();
      if (answer) kept.push(answer);
      continue;
    }

    kept.push(line);
  }

  return kept.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

// How much real content is left once markdown punctuation is discounted.
const substance = (text) => text.replace(/[>#|*_\-\s]/g, '').length;

const sections = markdown.split(/\n(?=## )/g);
const chunks = [];

for (const section of sections) {
  const text = section.trim();
  if (!text) continue;

  // The preamble above the first '## ' explains the file to whoever edits it; it says
  // nothing about Carlo.
  if (!text.startsWith('## ')) continue;

  const heading = (text.match(/^##\s+(.+)$/m)?.[1] ?? 'Overview')
    .replace(/^\d+\.\s*/, '')
    .trim();

  // The out-of-scope section is an instruction to the bot, already in the system prompt.
  // Indexing it would let a question about salary retrieve the word "salary" and burn a
  // retrieval slot on the rule instead of on content.
  if (/out of scope/i.test(heading)) continue;

  const body = stripScaffolding(text);
  if (substance(body) < MIN_SUBSTANCE) continue;

  if (body.length <= MAX_CHARS) {
    chunks.push({ section: heading, content: body });
    continue;
  }

  let buffer = '';
  for (const para of body.split(/\n\n+/)) {
    if ((buffer + '\n\n' + para).length > MAX_CHARS && buffer) {
      chunks.push({ section: heading, content: buffer.trim() });
      buffer = para;
    } else {
      buffer = buffer ? buffer + '\n\n' + para : para;
    }
  }
  if (buffer.trim()) chunks.push({ section: heading, content: buffer.trim() });
}

if (!chunks.length) {
  throw new Error('KB produced no chunks — is it still all TODOs?');
}

return chunks.map((c) => ({ json: c }));
